<?php
namespace RealEstateAI\AI;
defined( 'ABSPATH' ) || exit;
final class DeepSeek_Provider implements AI_Provider_Interface { private const BASE_URL='https://api.deepseek.com/v1/chat/completions'; public function chat(string $system,string $user,array $options=[]):array{ $key=defined('RE_PRO_DEEPSEEK_API_KEY')&&RE_PRO_DEEPSEEK_API_KEY?(string)RE_PRO_DEEPSEEK_API_KEY:(string)get_option('re_pro_deepseek_key',''); if(''===$key){throw new \RuntimeException(__('DeepSeek API key is not configured.','realestate-ai'));} $body=['model'=>!empty($options['model'])?sanitize_text_field($options['model']):'deepseek-chat','messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$user]],'temperature'=>isset($options['temperature'])?(float)$options['temperature']:0.2]; for($attempt=1;$attempt<=3;$attempt++){ $r=wp_remote_post(self::BASE_URL,['timeout'=>30,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json','Accept'=>'application/json'],'body'=>wp_json_encode($body)]); if(is_wp_error($r)){ $error=$r->get_error_message(); } else { $status=(int)wp_remote_retrieve_response_code($r); $data=json_decode(wp_remote_retrieve_body($r),true); if($status>=200&&$status<300&&is_array($data)){return ['text'=>(string)($data['choices'][0]['message']['content']??''),'usage'=>$data['usage']??[],'raw'=>$data];} $error=sanitize_text_field($data['error']['message']??sprintf('HTTP %d',$status)); if(!($status===429||$status>=500)){throw new \RuntimeException($error,$status);} } if($attempt<3){sleep(min(2**($attempt-1),8));}} throw new \RuntimeException($error??__('DeepSeek request failed.','realestate-ai')); } }
